  "sourceRoot": "",
  "metadata": {
    "semio": {
      "taxonomy": "🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/🔣️taxonomy.json",
      "dashboard": {
        "parameters": [
          {
            "id": "cache",
            "kind": "choice",
            "appliesTo": {
              "verbs": [
                "test",
                "check",
                "build",
                "verify",
                "lint",
                "serve",
                "activate",
                "task"
              ],
              "playground": false
            },
            "default": "use",
            "values": [
              {
                "id": "use"
              },
              {
                "id": "skip-local",
                "nxFlags": [
                  "--skip-nx-cache"
                ]
              },
              {
                "id": "skip-all",
                "nxFlags": [
                  "--skip-nx-cache",
                  "--skip-remote-cache"
                ]
              }
            ]
          },
          {
            "id": "test-level",
            "kind": "choice",
            "appliesTo": {
              "verbs": [
                "test",
                "verify",
                "check"
              ],
              "playground": false
            },
            "values": [
              {
                "id": "quick",
                "env": {
                  "SEMIO_TEST_LEVEL": "quick"
                }
              },
              {
                "id": "long",
                "env": {
                  "SEMIO_TEST_LEVEL": "long"
                }
              },
              {
                "id": "exhaustive",
                "env": {
                  "SEMIO_TEST_LEVEL": "exhaustive"
                }
              }
            ]
          },
          {
            "id": "dependencies",
            "kind": "flag",
            "appliesTo": {
              "verbs": [
                "test",
                "verify",
                "check",
                "task"
              ],
              "playground": false
            },
            "nxFlags": [
              "--excludeTaskDependencies"
            ]
          },
          {
            "id": "build-mode",
            "kind": "choice",
            "appliesTo": {
              "verbs": [
                "test",
                "verify",
                "build",
                "task"
              ],
              "playground": false
            },
            "values": [
              {
                "id": "ship",
                "env": {
                  "SEMIO_BUILD_MODE": "ship"
                },
                "nxFlags": [
                  "--skip-nx-cache",
                  "--skip-remote-cache"
                ]
              }
            ]
          },
          {
            "id": "nextest-output",
            "kind": "choice",
            "appliesTo": {
              "verbs": [
                "test"
              ],
              "playground": false
            },
            "values": [
              {
                "id": "immediate",
                "env": {
                  "NEXTEST_SUCCESS_OUTPUT": "immediate"
                }
              },
              {
                "id": "immediate-final",
                "env": {
                  "NEXTEST_SUCCESS_OUTPUT": "immediate-final"
                }
              },
              {
                "id": "final",
                "env": {
                  "NEXTEST_SUCCESS_OUTPUT": "final"
                }
              },
              {
                "id": "never",
                "env": {
                  "NEXTEST_SUCCESS_OUTPUT": "never"
                }
              }
            ]
          },
          {
            "id": "cargo-jobs",
            "kind": "text",
            "appliesTo": {
              "verbs": [
                "test",
                "check",
                "task"
              ],
              "playground": false
            },
            "valueEnv": "CARGO_BUILD_JOBS"
          },
          {
            "id": "build-budget",
            "kind": "text",
            "appliesTo": {
              "verbs": [
                "test",
                "serve",
                "activate",
                "task"
              ],
              "playground": false
            },
            "valueEnv": "SEMIO_BUILD_BUDGET_MS"
          }
        ],
        "tools": [
          {
            "id": "repo-mcp",
            "verb": "dev",
            "command": [
              "bun",
              "📜️script.ts",
              "dev",
              "mcp",
              "stdio"
            ],
            "continuous": true,
            "parameters": [
              {
                "id": "client",
                "kind": "text",
                "default": "client",
                "valuePositional": true
              }
