# never embedded inside a shipped plugin component (see `🖥️host`'s docstring), so there is no
# wasip2 arm here.
[target.'cfg(all(target_arch = "wasm32", not(target_env = "p2")))'.dependencies]
wgpu = { version = "29.0.4", default-features = false, features = ["std", "webgpu", "wgsl"] }
